package br.com.brindespro.order;
import br.com.brindespro.quote.*;import br.com.brindespro.admin.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;import java.time.*;import java.util.*;
@Service public class OrderService {
  private static final Set<String> STATUSES=Set.of("RECEBIDO","EM_ANALISE","AGUARDANDO_APROVACAO","APROVADO","EM_PRODUCAO","ENVIADO","ENTREGUE","CANCELADO");
  private final QuoteRepository quotes;private final OrderStatusHistoryRepository history;private final AuditLogRepository audits;
  public OrderService(QuoteRepository quotes,OrderStatusHistoryRepository history,AuditLogRepository audits){this.quotes=quotes;this.history=history;this.audits=audits;}
  public record HistoryDto(Long id,String status,String note,String createdAt){}
  public record OrderDto(QuoteService.QuoteDto order,List<HistoryDto> history){}
  public record UpdateRequest(String status,String internalNote,String expectedDeliveryDate,String trackingCode){}
  public OrderDto track(String number,String email){Quote q=quotes.findByNumberAndCustomer_EmailIgnoreCase(number.trim(),email.trim()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Pedido não encontrado."));return dto(q,true);}
  public List<QuoteService.QuoteDto> list(String search,String status,String from,String to){return quotes.findAll().stream().filter(q->search==null||search.isBlank()||q.number.toLowerCase().contains(search.toLowerCase())||q.customer.name.toLowerCase().contains(search.toLowerCase())).filter(q->status==null||status.isBlank()||q.orderStatus.equals(status)).filter(q->from==null||from.isBlank()||!q.createdAt.toLocalDate().isBefore(LocalDate.parse(from))).filter(q->to==null||to.isBlank()||!q.createdAt.toLocalDate().isAfter(LocalDate.parse(to))).sorted(Comparator.comparing((Quote q)->q.createdAt).reversed()).map(QuoteService::dto).toList();}
  public OrderDto detail(Long id){return dto(quotes.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Pedido não encontrado.")),false);}
  @Transactional public OrderDto update(Long id,UpdateRequest input,String email){if(input.status()==null||!STATUSES.contains(input.status()))throw new IllegalArgumentException("Status de pedido inválido.");Quote q=quotes.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Pedido não encontrado."));q.orderStatus=input.status();q.status=display(input.status());q.internalNote=input.internalNote()==null?"":input.internalNote();q.expectedDeliveryDate=input.expectedDeliveryDate()==null||input.expectedDeliveryDate().isBlank()?null:LocalDate.parse(input.expectedDeliveryDate());q.trackingCode=input.trackingCode()==null?"":input.trackingCode().trim();q.updatedAt=OffsetDateTime.now();Quote saved=quotes.save(q);history.save(new OrderStatusHistory(saved,input.status(),"",true,email));audits.save(new AuditLog(null,"Order",saved.id,"STATUS",input.status()+" | "+q.internalNote));return dto(saved,false);}
  public List<Map<String,Object>> notifications(){List<Map<String,Object>> out=new ArrayList<>();for(Quote q:quotes.findAll()){if(q.orderStatus.equals("RECEBIDO"))out.add(notification(q,"NOVO_PEDIDO","Novo pedido aguardando análise"));if(q.orderStatus.equals("AGUARDANDO_APROVACAO"))out.add(notification(q,"AGUARDANDO_APROVACAO","Pedido aguardando aprovação"));if(q.expectedDeliveryDate!=null&&q.expectedDeliveryDate.isBefore(LocalDate.now())&&!Set.of("ENTREGUE","CANCELADO").contains(q.orderStatus))out.add(notification(q,"ATRASADO","Previsão de entrega vencida"));}return out.stream().sorted((a,b)->((String)b.get("createdAt")).compareTo((String)a.get("createdAt"))).toList();}
  private Map<String,Object> notification(Quote q,String type,String label){return Map.of("id",type+"-"+q.id,"type",type,"message",label+": "+q.number,"orderId",q.id,"createdAt",q.updatedAt.toString());}
  private OrderDto dto(Quote q,boolean publicView){List<HistoryDto> list=(publicView?history.findByQuote_IdAndVisibleToCustomerTrueOrderByCreatedAtAsc(q.id):history.findByQuote_IdOrderByCreatedAtAsc(q.id)).stream().map(h->new HistoryDto(h.id,h.status,h.note,h.createdAt.toString())).toList();return new OrderDto(QuoteService.dto(q),list);}
  private String display(String status){return switch(status){case "EM_ANALISE"->"Em análise";case "AGUARDANDO_APROVACAO"->"Aguardando aprovação";case "EM_PRODUCAO"->"Em produção";case "ENVIADO"->"Enviado";case "ENTREGUE"->"Entregue";case "CANCELADO"->"Cancelado";case "APROVADO"->"Aprovado";default->"Recebido";};}
}
